CREATE TABLE residence_sync (
  residence_id TEXT PRIMARY KEY,
  version INTEGER NOT NULL DEFAULT 0
);
INSERT INTO residence_sync(residence_id,version) SELECT id,0 FROM residences;
CREATE TRIGGER sync_residences_update AFTER UPDATE ON residences BEGIN INSERT INTO residence_sync(residence_id,version) VALUES(NEW.id,1) ON CONFLICT(residence_id) DO UPDATE SET version=version+1; END;
CREATE TRIGGER sync_users_insert AFTER INSERT ON users BEGIN INSERT INTO residence_sync(residence_id,version) VALUES(NEW.residence_id,1) ON CONFLICT(residence_id) DO UPDATE SET version=version+1; END;
